UIWelderSmokeParticle=function(game,x,y){Phaser.Particle.call(this,game,x,y,game.cache.getBitmapData('weldersmoke'+Math.floor(Math.random()*2)));this.kill();};UIWelderSmokeParticle.prototype=Object.create(Phaser.Particle.prototype);UIWelderSmokeParticle.prototype.constructor=UIWelderSmokeParticle;UIWelderSmokeParticle.prototype.onEmit=function(){var xx=Math.floor(Math.random()*UIWelderSmokeParticle.spawnPoints.length);var randomSpawnPoint=UIWelderSmokeParticle.spawnPoints[xx];this.x=UIWelderSmokeParticle.tankIcon.world.x+randomSpawnPoint.x*UIWelderSmokeParticle.tankIcon.width;this.y=UIWelderSmokeParticle.tankIcon.world.y+randomSpawnPoint.y*UIWelderSmokeParticle.tankIcon.height;};UIWelderSmokeParticle.prototype.update=function(){this.alpha=Math.max(0.0,this.alpha-(0.01-Math.random()*0.004));this.scale.set(this.scale.x+0.0125,this.scale.y+0.0125);};UIWelderSmokeParticle.prototype.retire=function(){this.kill();};UIWelderSmokeParticle.updateSpark=function(game){var randomIntensity=Math.floor(Math.random()*64);UIWelderSmokeParticle._drawSparkSmoke(game.cache.getBitmapData('weldersmoke0'),172+randomIntensity);UIWelderSmokeParticle._drawSparkSmoke(game.cache.getBitmapData('weldersmoke1'),128+randomIntensity);};UIWelderSmokeParticle._drawSparkSmoke=function(welderSmoke,intensity){welderSmoke.clear();var radGrad=welderSmoke.context.createRadialGradient(UIConstants.WELDER_SMOKE_RADIUS,UIConstants.WELDER_SMOKE_RADIUS,UIConstants.WELDER_SMOKE_INNER_RADIUS,UIConstants.WELDER_SMOKE_RADIUS,UIConstants.WELDER_SMOKE_RADIUS,UIConstants.WELDER_SMOKE_RADIUS);radGrad.addColorStop(0,'rgba('+intensity+', '+intensity+', '+intensity+', 1)');radGrad.addColorStop(1,'rgba('+intensity+', '+intensity+', '+intensity+', 0)');welderSmoke.context.fillStyle=radGrad;welderSmoke.context.fillRect(0,0,UIConstants.WELDER_SMOKE_RADIUS*2,UIConstants.WELDER_SMOKE_RADIUS*2);welderSmoke.dirty=true;};UIWelderSmokeParticle.setSpawnPoints=function(tankIcon,spawnPointsOld,spawnPointsNew){UIWelderSmokeParticle.spawnPoints=[];UIWelderSmokeParticle.tankIcon=tankIcon;if(spawnPointsOld){UIWelderSmokeParticle.spawnPoints=UIWelderSmokeParticle.spawnPoints.concat(spawnPointsOld);}if(spawnPointsNew){UIWelderSmokeParticle.spawnPoints=UIWelderSmokeParticle.spawnPoints.concat(spawnPointsNew);}};